 ?> settled predictions</span><span><?php if ($hub['page'] > 1): ?><a href="<?= e($queryLink(['page' => $hub['page'] - 1])) ?>">← Previous</a> &nbsp;<?php endif ?>Page <?= (int) $hub['page'] ?> of <?= (int) $hub['pages'] ?><?php if ($hub['page'] < $hub['pages']): ?> &nbsp;<a href="<?= e($queryLink(['page' => $hub['page'] + 1])) ?>">Next →</a><?php endif ?> &nbsp; · &nbsp; Synthetic results · Newest first</span></div><p class="sr-only" role="status" data-pl-feedback></p></section></div>
